<template><section class="business" v-loading="loading">
  <h1>作业管理</h1><p class="hint">布置时建立在读学生名单。完成率 =（已完成 + 迟交）/ 纳入统计的名单人数；排除记录不计分母。到期但未确认的记录显示“逾期待确认”，不自动算成未完成。</p>
  <div class="filters"><el-select v-model="filters.classId" clearable placeholder="全部班级" aria-label="作业班级"><el-option v-for="c in classes" :key="c.id" :value="c.id" :label="c.className+' · '+c.academicYear"/></el-select><el-input v-model="filters.subject" clearable placeholder="科目（精确匹配）" aria-label="作业科目"/><el-date-picker v-model="filters.from" type="date" value-format="YYYY-MM-DD" placeholder="布置开始日期" aria-label="作业开始日期"/><el-date-picker v-model="filters.to" type="date" value-format="YYYY-MM-DD" placeholder="布置结束日期" aria-label="作业结束日期"/><el-button :loading="loading" @click="search">查询</el-button><el-button v-if="isAdmin" type="primary" @click="open()">新建作业</el-button></div>
  <MobileList v-if="narrow" :items="rows" :primary="r=>r.name" :secondary="r=>r.className" :badge="r=>r.subject"
    empty="暂无作业"
    :fields="[{k:'assignedDate',label:'布置日期'},{k:'deadline',label:'截止时间'},{k:'description',label:'描述'}]">
    <template #actions="{row}"><el-button link type="primary" @click="selectAssignment(row)">完成情况</el-button><el-button v-if="isAdmin" link @click="open(row)">编辑</el-button><el-button v-if="isAdmin" link type="danger" @click="remove(row)">删除</el-button></template>
  </MobileList>
  <el-table v-else :data="rows" empty-text="暂无作业"><el-table-column prop="name" label="作业名称" min-width="150"/><el-table-column prop="className" label="班级" min-width="130"/><el-table-column prop="subject" label="科目" width="80"/><el-table-column prop="assignedDate" label="布置日期" width="120"/><el-table-column prop="deadline" label="截止时间" min-width="180"/><el-table-column prop="description" label="描述" min-width="150"/><el-table-column fixed="right" label="操作" width="210"><template #default="{row}"><el-button link type="primary" @click="selectAssignment(row)">完成情况</el-button><el-button v-if="isAdmin" link @click="open(row)">编辑</el-button><el-button v-if="isAdmin" link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table>
  <el-pagination v-model:current-page="page" :total="total" :page-size="10" :pager-count="5" layout="total,prev,pager,next" @current-change="load"/>
  <h2 class="subheading">{{selected?'完成情况：'+selected.name:'学生历史作业情况'}}</h2><div class="filters"><StudentPicker v-model="studentId" :class-id="filters.classId"/><el-select v-model="state" clearable placeholder="全部状态" aria-label="作业状态筛选"><el-option v-for="(label,key) in labels" :key="key" :value="key" :label="label"/></el-select><el-button @click="recordPage=1;loadRecords()">查询完成记录</el-button><el-button @click="state='INCOMPLETE';recordPage=1;loadRecords()">未完成名单</el-button><el-button v-if="selected" @click="selected=null;recordPage=1;loadRecords()">查看全部作业</el-button><el-button v-if="selected&&isAdmin" @click="openState()">补充学生记录</el-button></div>
  <el-progress v-if="summary?.completionRate!==null&&summary?.completionRate!==undefined" :percentage="Number(summary.completionRate)" :stroke-width="10"/>
  <div v-if="summary" class="summary">统计分母 {{summary.denominator}} 人，排除 {{summary.excluded}} 人；完成率 {{summary.completionRate===null?'暂无数据':summary.completionRate+'%'}}。已完成 {{summary.COMPLETED}}，迟交 {{summary.LATE}}，未完成 {{summary.INCOMPLETE}}，待完成 {{summary.PENDING}}，逾期待确认 {{summary.UNCONFIRMED}}。</div>
  <el-table :data="records" v-loading="recordLoading" empty-text="暂无匹配记录；没有记录不代表未完成"><el-table-column prop="assignmentName" label="作业" min-width="130"/><el-table-column prop="studentNo" label="学号" min-width="110"/><el-table-column prop="studentName" label="学生" min-width="90"/><el-table-column label="状态" min-width="110"><template #default="{row}"><StatusTag :status="row.status"/></template></el-table-column><el-table-column prop="submittedAt" label="提交时间" min-width="180"/><el-table-column label="统计" width="80"><template #default="{row}">{{row.included?'纳入':'排除'}}</template></el-table-column><el-table-column prop="remark" label="备注" min-width="120"/><el-table-column v-if="isAdmin" fixed="right" label="操作" width="90"><template #default="{row}"><el-button link @click="openState(row)">改状态</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="recordPage" :total="recordTotal" :page-size="10" :pager-count="5" layout="total,prev,pager,next" @current-change="loadRecords"/>
  <el-dialog v-model="dialog" :title="form.id?'编辑作业':'新建作业'" width="min(560px,94vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="作业名称（必填）"><el-input v-model="form.name" maxlength="100"/></el-form-item><el-form-item label="班级（布置后不能更换）"><el-select v-model="form.classId" :disabled="!!form.id"><el-option v-for="c in classes" :key="c.id" :value="c.id" :label="c.className+' · '+c.academicYear"/></el-select></el-form-item><el-form-item label="科目（必填）"><el-input v-model="form.subject" maxlength="50"/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" maxlength="2000"/></el-form-item><el-form-item label="布置日期（必填）"><el-date-picker v-model="form.assignedDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="截止时间（必填）"><el-date-picker v-model="form.deadline" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="stateDialog" title="修改作业完成状态" width="min(520px,94vw)" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="学生"><StudentPicker v-model="stateForm.studentId" :class-id="selected?.classId"/></el-form-item><el-form-item label="状态"><el-select v-model="stateForm.status" @change="stateForm.submittedAt=null"><el-option v-for="key in ['PENDING','COMPLETED','INCOMPLETE','LATE']" :key="key" :value="key" :label="labels[key]"/></el-select></el-form-item><el-form-item v-if="['COMPLETED','LATE'].includes(stateForm.status)" label="提交时间（后端据此判定是否迟交）"><el-date-picker v-model="stateForm.submittedAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="备注"><el-input v-model="stateForm.remark" type="textarea" maxlength="500"/></el-form-item><el-checkbox v-model="stateForm.included">纳入完成率统计</el-checkbox></el-form><template #footer><el-button @click="stateDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveState">保存状态</el-button></template></el-dialog>
</section></template>
<script setup>
import MobileList from '../components/MobileList.vue';
import {useNarrow} from '../composables/useNarrow';
const narrow=useNarrow();

import StatusTag from '../components/StatusTag.vue';
import {ref,reactive,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import api from '../api';import StudentPicker from '../components/StudentPicker.vue';import './business.css';
defineProps({classes:Array,isAdmin:Boolean});
const labels={PENDING:'待完成',COMPLETED:'已完成',INCOMPLETE:'未完成',LATE:'迟交',UNCONFIRMED:'逾期待确认'};
const filters=reactive({classId:null,subject:'',from:null,to:null}),rows=ref([]),records=ref([]),page=ref(1),total=ref(0),recordPage=ref(1),recordTotal=ref(0),studentId=ref(),state=ref(),selected=ref(),summary=ref(),loading=ref(false),recordLoading=ref(false),saving=ref(false),dialog=ref(false),stateDialog=ref(false),form=reactive({}),stateForm=reactive({});
let loadSequence=0,recordSequence=0;
const error=e=>ElMessage.error(e.response?.data?.message||e.message||'请求失败');
function params(){return Object.fromEntries(Object.entries(filters).filter(([,v])=>v!==null&&v!==''&&v!==undefined))}
async function load(){const request=++loadSequence;loading.value=true;try{const r=await api.get('/assignments',{params:{...params(),page:page.value-1}});if(request!==loadSequence)return;rows.value=r.data.data.content;total.value=r.data.data.total}catch(e){error(e)}finally{if(request===loadSequence)loading.value=false}}
async function loadRecords(){const request=++recordSequence;recordLoading.value=true;try{const [r,s]=await Promise.all([api.get('/assignments/records',{params:{...params(),assignmentId:selected.value?.id,studentId:studentId.value||undefined,status:state.value||undefined,page:recordPage.value-1}}),selected.value?api.get(`/assignments/${selected.value.id}/statistics`):Promise.resolve(null)]);if(request!==recordSequence)return;records.value=r.data.data.content;recordTotal.value=r.data.data.total;summary.value=s?.data.data}catch(e){error(e)}finally{if(request===recordSequence)recordLoading.value=false}}
function search(){page.value=1;recordPage.value=1;selected.value=null;load();loadRecords()}
function selectAssignment(row){selected.value=row;studentId.value=null;state.value=null;recordPage.value=1;loadRecords()}
function open(row){Object.assign(form,{id:null,name:'',classId:filters.classId,subject:'',description:'',assignedDate:null,deadline:null},row||{});dialog.value=true}
async function save(){if(saving.value)return;if(!form.name?.trim()||!form.classId||!form.subject?.trim()||!form.assignedDate||!form.deadline)return ElMessage.warning('请填写名称、班级、科目和日期');saving.value=true;try{await api({url:form.id?`/assignments/${form.id}`:'/assignments',method:form.id?'put':'post',data:form});dialog.value=false;await load();if(selected.value?.id===form.id)selected.value={...form};await loadRecords();ElMessage.success('作业已保存')}catch(e){error(e)}finally{saving.value=false}}
async function remove(row){try{await ElMessageBox.confirm(`将作业「${row.name}」及其全部完成记录移入回收站？之后可以整批恢复。`,'移入回收站',{type:'warning',confirmButtonText:'移入回收站',cancelButtonText:'取消'});const r=await api.delete(`/assignments/${row.id}`);if(selected.value?.id===row.id){selected.value=null;recordPage.value=1}if(rows.value.length===1&&page.value>1)page.value--;await load();await loadRecords();ElMessage.success(`已移入回收站，含 ${r.data.data.deleted} 条记录`)}catch(e){if(e!=='cancel'&&e!=='close')error(e)}}
function openState(row){Object.assign(stateForm,{studentId:null,assignmentId:selected.value?.id,status:'PENDING',submittedAt:null,remark:'',included:true},row||{});if(stateForm.status==='UNCONFIRMED')stateForm.status='INCOMPLETE';stateDialog.value=true}
async function saveState(){if(saving.value)return;if(!stateForm.studentId||(['COMPLETED','LATE'].includes(stateForm.status)&&!stateForm.submittedAt))return ElMessage.warning('请选择学生并填写提交时间');saving.value=true;try{await api.put(`/assignments/${stateForm.assignmentId}/students/${stateForm.studentId}`,stateForm);stateDialog.value=false;await loadRecords();ElMessage.success('状态已保存')}catch(e){error(e)}finally{saving.value=false}}
onMounted(()=>{load();loadRecords()});
</script>
